<?php
require_once __DIR__.'/../config.php'; require_once __DIR__.'/../includes/functions.php'; $pageTitle='Teachers'; require_role(['admin']); require_once __DIR__.'/../includes/header.php';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$pdo->beginTransaction();$staffNo=next_registration_number($pdo,'teacher');$temp=generate_temp_password();$username='teacher.'.strtolower(str_replace('/','.',str_replace(' ','',$staffNo)));$name=trim($_POST['full_name']);$st=$pdo->prepare("INSERT INTO users(username,password_hash,role,full_name,email,phone,must_change_password) VALUES(?,?,?,?,?,?,1)");$st->execute([$username,password_hash($temp,PASSWORD_DEFAULT),'teacher',$name,trim($_POST['email']??'')?:null,trim($_POST['phone']??'')?:null]);$uid=(int)$pdo->lastInsertId();$st=$pdo->prepare("INSERT INTO teachers(user_id,staff_no,qualification,hire_date,address) VALUES(?,?,?,?,?)");$st->execute([$uid,$staffNo,trim($_POST['qualification']??''),$_POST['hire_date']?:null,trim($_POST['address']??'')]);$tid=(int)$pdo->lastInsertId();$pdo->commit();audit($pdo,'create','teachers',$tid,'Staff registration number '.$staffNo);flash('success','Teacher registered. Staff/registration number: '.$staffNo.' | Username: '.$username.' | First password: '.$temp);redirect('teachers.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getCode()==='23000'?'A unique username/email already exists.':'Could not register teacher.';}}
$rows=$pdo->query("SELECT t.*,u.full_name,u.username,u.email,u.phone,u.status FROM teachers t JOIN users u ON u.id=t.user_id ORDER BY u.full_name")->fetchAll();$success=flash('success');
?><h2>Teacher Registration</h2><?php if($success): ?><div class="alert alert-success"><strong>Save these credentials securely:</strong><br><?=e($success)?></div><?php endif;?><?php if($error): ?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="card p-4 mb-4"><form method="post" class="row g-3"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="col-md-4"><label>Full name</label><input class="form-control" name="full_name" required></div><div class="col-md-2"><label>Email</label><input class="form-control" type="email" name="email"></div><div class="col-md-2"><label>Phone</label><input class="form-control" name="phone"></div><div class="col-md-4"><label>Qualification</label><input class="form-control" name="qualification"></div><div class="col-md-3"><label>Hire date</label><input class="form-control" type="date" name="hire_date"></div><div class="col-md-6"><label>Address</label><input class="form-control" name="address"></div><div class="col-12"><button class="btn btn-primary">Register teacher & generate first password</button></div></form></div><div class="card p-3 table-responsive"><table class="table"><thead><tr><th>Staff No.</th><th>Name</th><th>Username</th><th>Email</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=e($r['staff_no'])?></td><td><?=e($r['full_name'])?></td><td><?=e($r['username'])?></td><td><?=e($r['email'])?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/../includes/footer.php';
